using UnityEngine;

public static class RectTransformExtensions
{
	public static void SetSizeDeltaX(this RectTransform t, float value)
	{
		t.sizeDelta = new Vector2(value, t.sizeDelta.y);
	}

	public static void SetSizeDeltaY(this RectTransform t, float value)
	{
		t.sizeDelta = new Vector2(t.sizeDelta.x, value);
	}

	public static void SetAnchoredPositionX(this RectTransform t, float value)
	{
		t.anchoredPosition = new Vector2(value, t.anchoredPosition.y);
	}

	public static void SetAnchoredPositionY(this RectTransform t, float value)
	{
		t.anchoredPosition = new Vector2(t.anchoredPosition.x, value);
	}

	public static void SetRotationEulerAnglesZ(this RectTransform t, float value)
	{
		t.eulerAngles = new Vector3(t.rotation.x, t.rotation.y, value);
	}

	public static void SetRotationLocalEulerAnglesZ(this RectTransform t, float value)
	{
		t.localEulerAngles = new Vector3(t.rotation.x, t.rotation.y, value);
	}

	public static void SetAnchorToRectCorners(this RectTransform rectTransform)
	{
		Rect rect = rectTransform.rect;
		Vector2 anchoredPosition = rectTransform.anchoredPosition;
		RectTransform component = rectTransform.parent.GetComponent<RectTransform>();
		float num = rect.width * rectTransform.pivot.x;
		float num2 = rect.height * (1f - rectTransform.pivot.y);
		Vector2 vector = new Vector2(rectTransform.anchorMin.x * component.rect.width + rectTransform.offsetMin.x + num - component.rect.width * anchoredPosition.x, (0f - (1f - rectTransform.anchorMax.y)) * component.rect.height + rectTransform.offsetMax.y - num2 + component.rect.height * (1f - anchoredPosition.y));
		rect.x = vector.x;
		rect.y = vector.y;
		rect.width = rectTransform.rect.width;
		rect.height = rectTransform.rect.height;
		num = rect.width * rectTransform.pivot.x;
		num2 = rect.height * (1f - rectTransform.pivot.y);
		rectTransform.anchorMin = new Vector2(0f, 1f);
		rectTransform.anchorMax = new Vector2(0f, 1f);
		rectTransform.offsetMin = new Vector2(rect.x / rectTransform.localScale.x, rect.y / rectTransform.localScale.y - rect.height);
		rectTransform.offsetMax = new Vector2(rect.x / rectTransform.localScale.x + rect.width, rect.y / rectTransform.localScale.y);
		rectTransform.anchorMin = new Vector2(rectTransform.anchorMin.x + anchoredPosition.x + (rectTransform.offsetMin.x - num) / component.rect.width * rectTransform.localScale.x, rectTransform.anchorMin.y - (1f - anchoredPosition.y) + (rectTransform.offsetMin.y + num2) / component.rect.height * rectTransform.localScale.y);
		rectTransform.anchorMax = new Vector2(rectTransform.anchorMax.x + anchoredPosition.x + (rectTransform.offsetMax.x - num) / component.rect.width * rectTransform.localScale.x, rectTransform.anchorMax.y - (1f - anchoredPosition.y) + (rectTransform.offsetMax.y + num2) / component.rect.height * rectTransform.localScale.y);
		rectTransform.offsetMin = new Vector2((0f - rectTransform.pivot.x) * rect.width * (1f - rectTransform.localScale.x), (0f - rectTransform.pivot.y) * rect.height * (1f - rectTransform.localScale.y));
		rectTransform.offsetMax = new Vector2((1f - rectTransform.pivot.x) * rect.width * (1f - rectTransform.localScale.x), (1f - rectTransform.pivot.y) * rect.height * (1f - rectTransform.localScale.y));
		_ = rectTransform.offsetMin;
		_ = rectTransform.offsetMax;
	}
}
